rules.pseudocode:
correctionBars = currentBarIndex - barIndexOf(patternExtreme);
patternBars = barIndexOf(patternExtreme) - barIndexOf(firstPush);
correctionAdequate = correctionBars >= minCorrectionFraction * patternBars

flagHigh = highest(high, flagBars)[1]; flagLow = lowest(low, flagBars)[1];
brokeOut = requirePriorBreakout == 0 || (highest(high, priorBreakoutWindow)[1] > flagHigh);
isFinalFlagCandidate[1] && brokeOut && close[0] < flagLow

// long-side reading on a wedge TOP being faded short; mirrored on lows
late  = swingHigh(1, s) - swingHigh(2, s);
early = swingHigh(2, s) - swingHigh(3, s);
if perBar == 1 { late = late / barsBetween(swingHigh(1,s), swingHigh(2,s)); early = early / barsBetween(swingHigh(2,s), swingHigh(3,s)); }
isAccelerating = early > 0 && late > early * accelMultiple

// long: target the pivotIndex-th most recent swing high
target = swingHigh(pivotIndex, swingStrength);
ctx.MarketPosition() > 0 && high[0] >= target
